CREATE OR REPLACE FUNCTION public.phase5_programplan_package_levels(catalog_id text, kind text, levels jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare payload jsonb;l jsonb;s jsonb;i jsonb;k text;keys text[]:='{}';total integer:=0;
begin
 if kind is null or kind not in ('languageSubject','naturalScience','specialization','individualChoice')
  or not public.phase5_programplan_array(levels,200) then raise exception 'Invalid subject package' using errcode='22023';end if;
 if jsonb_array_length(levels)=0 then raise exception 'Invalid subject package' using errcode='22023';end if;
 select c.payload into payload from public.programplan_catalogs c where c.catalog_id=phase5_programplan_package_levels.catalog_id;
 if not found then raise exception 'Invalid package catalog' using errcode='22023';end if;
 for l in select value from jsonb_array_elements(levels) loop
  if not public.phase5_programplan_shape(l,array['subjectCode','subjectVersion','itemCode','points'])
   or not public.phase5_programplan_code(l->'subjectCode') or not public.phase5_programplan_code(l->'itemCode')
   or not public.phase5_programplan_integer(l->'subjectVersion',1,100000) or not public.phase5_programplan_integer(l->'points',1,10000)
   or l->>'subjectCode' in ('MODY','MODG','MODO','MODF','MODE')
   or (kind='languageSubject' and l->>'subjectCode' not in ('ENGE','KLAS','LATI'))
   or (kind='naturalScience' and l->>'subjectCode' not in ('BIOG','BIOE','FYSK','FYSF','KEMI')) then raise exception 'Invalid subject package level' using errcode='22023';end if;
  select value into s from jsonb_array_elements(payload->'subjects') where value->>'code'=l->>'subjectCode' and value->'version'=l->'subjectVersion';
  select value into i from jsonb_array_elements(coalesce(s->'items','[]'::jsonb)) where value->>'code'=l->>'itemCode';
  if s is null or i is null or i->'points' is distinct from l->'points' or not(s->'schoolTypes'?'GY') or s->>'typeOfSyllabus' is distinct from 'GRADE_SUBJECT_SYLLABUS' then raise exception 'Invalid subject package level' using errcode='22023';end if;
  k:=(l->>'subjectCode')||':'||(l->>'subjectVersion')||':'||(l->>'itemCode');
  if k=any(keys) then raise exception 'Duplicate subject package level' using errcode='22023';end if;
  keys:=array_append(keys,k);total:=total+(l->>'points')::integer;
 end loop;
 if total>10000 then raise exception 'Invalid subject package points' using errcode='22023';end if;
 return total;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_payload_valid(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s jsonb; p jsonb; o jsonb; i jsonb; school jsonb; seen text[]:='{}'; item_seen text[]:='{}'; schools_seen text[]; orientation_seen text[]; prior text; current_code text; src jsonb;
begin
 if not public.phase5_programplan_shape(v,array['schemaVersion','source','subjects','programs']) or v->'schemaVersion' is distinct from '1'::jsonb
  or not public.phase5_programplan_array(v->'subjects',20000) or not public.phase5_programplan_array(v->'programs',1000) then return false; end if;
 src:=v->'source';
 if not public.phase5_programplan_shape(src,array['url','apiVersion','fetched']) or not public.phase5_programplan_url(src->'url')
  or not public.phase5_programplan_text(src->'apiVersion',100) or not public.phase5_programplan_date(src->'fetched') then return false; end if;
 prior:=null;
 for s in select value from jsonb_array_elements(v->'subjects') loop
  if not public.phase5_programplan_shape(s,array['code','name','typeOfSyllabus','schoolTypes','version','items','startDate','endDate','canceledDate','skolfs'])
   or not public.phase5_programplan_code(s->'code') or not public.phase5_programplan_text(s->'name') or not public.phase5_programplan_code(s->'typeOfSyllabus')
   or not public.phase5_programplan_integer(s->'version',1,100000) or not public.phase5_programplan_dates(s)
   or not public.phase5_programplan_array(s->'schoolTypes',20) or jsonb_array_length(s->'schoolTypes')=0
   or not public.phase5_programplan_array(s->'items',1000) then return false; end if;
  current_code:=s->>'code'; if current_code=any(seen) or (prior is not null and current_code collate "C"<=prior collate "C") then return false; end if;
  prior:=current_code; seen:=array_append(seen,current_code); schools_seen:='{}';
  for school in select value from jsonb_array_elements(s->'schoolTypes') loop
   if not public.phase5_programplan_code(school) or school#>>'{}'=any(schools_seen) then return false; end if;
   if cardinality(schools_seen)>0 and (school#>>'{}') collate "C"<=schools_seen[cardinality(schools_seen)] collate "C" then return false; end if;
   schools_seen:=array_append(schools_seen,school#>>'{}');
  end loop;
  for i in select value from jsonb_array_elements(s->'items') loop
   if not public.phase5_programplan_item(i) or i->>'code'=any(item_seen) then return false; end if;
   item_seen:=array_append(item_seen,i->>'code');
  end loop;
 end loop;
 seen:='{}'; prior:=null;
 for p in select value from jsonb_array_elements(v->'programs') loop
  if not public.phase5_programplan_shape(p,array['code','name','category','version','foundation','programmeSpecific','orientations','specialization','startDate','endDate','canceledDate','skolfs'])
   or not public.phase5_programplan_code(p->'code') or not public.phase5_programplan_text(p->'name') or not public.phase5_programplan_code(p->'category')
   or not public.phase5_programplan_integer(p->'version',1,100000) or not public.phase5_programplan_dates(p)
   or not public.phase5_programplan_block_valid(p->'foundation',v->'subjects') or not public.phase5_programplan_block_valid(p->'programmeSpecific',v->'subjects')
   or not public.phase5_programplan_block_valid(p->'specialization',v->'subjects') or not public.phase5_programplan_array(p->'orientations',100) then return false; end if;
  current_code:=p->>'code'; if current_code=any(seen) or (prior is not null and current_code collate "C"<=prior collate "C") then return false; end if;
  prior:=current_code; seen:=array_append(seen,current_code); orientation_seen:='{}';
  for o in select value from jsonb_array_elements(p->'orientations') loop
   if not public.phase5_programplan_shape(o,array['code','name','points','subjects']) or not public.phase5_programplan_code(o->'code') or not public.phase5_programplan_text(o->'name')
    or not public.phase5_programplan_integer(o->'points',0,10000) or not public.phase5_programplan_block_valid(o->'subjects',v->'subjects') or o->>'code'=any(orientation_seen) then return false; end if;
   orientation_seen:=array_append(orientation_seen,o->>'code');
  end loop;
 end loop;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_resolved_selections(plan_id uuid, unit_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare p public.point_plans;up public.programplan_unit_packages;sel jsonb;e jsonb;entries jsonb;selections jsonb:='[]';
begin
 select * into p from public.point_plans where id=plan_id;
 if not found then raise exception 'Programplan denied' using errcode='42501';end if;
 select * into up from public.programplan_unit_packages x where x.plan_id=p.id and x.unit_id=phase5_programplan_resolved_selections.unit_id;
 for sel in select value from jsonb_array_elements(coalesce(up.selections,'[]'::jsonb)) loop
  entries:='[]';
  for e in select value from jsonb_array_elements(sel->'entries') loop entries:=entries||jsonb_build_array(public.phase5_programplan_validate_scoped_selection(p.basis_reference,sel->>'blockId',e,unit_id,p.organizer_id));end loop;
  selections:=selections||jsonb_build_array(jsonb_build_object('blockId',sel->'blockId','entries',entries));
 end loop;
 return jsonb_build_object('planId',p.id,'unitId',unit_id,'revision',coalesce(up.revision,0),'selections',selections);
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_scope(plan_id uuid, offering_id uuid DEFAULT NULL::uuid)
 RETURNS offerings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.access_assignments; o public.offerings;
begin
 a:=public.phase5_programplan_actor();
 select f.* into o from public.offerings f join public.organizers g on g.id=f.organizer_id and g.customer_id=a.customer_id
 where f.organizer_id=a.organizer_id and f.kind='gymnasium'
 and ((plan_id is not null and exists(select 1 from public.point_plans p where p.id=plan_id and p.offering_id=f.id and p.organizer_id=f.organizer_id)) or (plan_id is null and f.id=offering_id))
 and exists(select 1 from public.offering_units ou join public.mandate_units m on m.assignment_id=a.id and m.unit_id=ou.unit_id where ou.offering_id=f.id and ou.organizer_id=f.organizer_id);
 if not found then raise exception 'Programplan denied' using errcode='42501'; end if;
 -- Session -> kund -> skolor (id-ordning) -> utbildning -> planer.
 -- Kundlåset serialiserar skolval och mandat. Skolor låses före utbildningen
 -- så att skolimport/skapande inte får omvänd ordning.
 perform 1 from public.school_units u join public.offering_units ou on ou.unit_id=u.id and ou.organizer_id=u.organizer_id where ou.offering_id=o.id order by u.id for update of u;
 select * into o from public.offerings f where f.id=o.id for update;
 a:=public.phase5_programplan_actor();
 if o.id is null or o.organizer_id<>a.organizer_id or not exists(select 1 from public.organizers g where g.id=o.organizer_id and g.customer_id=a.customer_id)
 or not exists(select 1 from public.offering_units ou join public.mandate_units m on m.assignment_id=a.id and m.unit_id=ou.unit_id where ou.offering_id=o.id and ou.organizer_id=o.organizer_id)
 or (plan_id is not null and not exists(select 1 from public.point_plans p where p.id=plan_id and p.offering_id=o.id and p.organizer_id=o.organizer_id)) then
  raise exception 'Programplan denied' using errcode='42501'; end if;
 return o;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_selection(unit_id uuid, catalog_id text, program_ref jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.access_assignments; payload jsonb; result jsonb;
begin
 a:=public.phase5_programplan_actor();
 if (catalog_id is not null and (unit_id is null or catalog_id!~'^sha256:[0-9a-f]{64}$')) or (program_ref is not null and catalog_id is null)
 or (program_ref is not null and (jsonb_typeof(program_ref)<>'object' or (select count(*) from jsonb_object_keys(program_ref))<>2 or not program_ref?'code' or not program_ref?'version')) then
 raise exception 'Invalid selection' using errcode='22023';end if;
 if unit_id is not null then perform public.phase5_programplan_unit(unit_id);end if;
 if catalog_id is not null then select c.payload into payload from public.programplan_catalogs c where c.catalog_id=phase5_programplan_selection.catalog_id;
 if not found then raise exception 'Invalid catalog' using errcode='22023';end if;end if;
 select jsonb_build_object('units',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'name',u.name) order by u.name,u.id)
 from public.school_units u join public.organizers g on g.id=u.organizer_id and g.customer_id=a.customer_id
 join public.mandate_units m on m.assignment_id=a.id and m.unit_id=u.id
 where u.organizer_id=a.organizer_id and exists(select 1 from public.school_unit_types t where t.unit_id=u.id and t.school_type='GY')),'[]'::jsonb),
 'canCreateEducation',a.function='huvudman','catalogs',case when unit_id is null then '[]'::jsonb else coalesce((select jsonb_agg(jsonb_build_object('catalogId',c.catalog_id,'source',c.payload->'source') order by c.catalog_id) from public.programplan_catalogs c),'[]'::jsonb) end,
 'selection',jsonb_build_object('unitId',unit_id,'catalogId',catalog_id,'programRef',program_ref),'payload',payload,'decisionReady',false) into result;
 perform public.phase5_programplan_education_audit('programplan_selection_read',null,'education_collection');return result;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_session_check()
 RETURNS app_sessions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare s public.app_sessions; sid uuid; identity_id uuid; membership_id uuid; assignment_id uuid;
begin
 begin
  sid:=nullif(current_setting('app.session_id',true),'')::uuid;
  identity_id:=public.current_identity_id(); membership_id:=nullif(current_setting('app.membership_id',true),'')::uuid; assignment_id:=public.current_assignment_id();
 exception when invalid_text_representation then raise exception 'Programplan denied' using errcode='42501'; end;
 if sid is null or identity_id is null or membership_id is null or assignment_id is null then raise exception 'Programplan denied' using errcode='42501'; end if;
 -- Always before the customer lock on the first invocation, including postgres fixtures.
 select * into s from public.app_sessions where id=sid for update;
 if not found or s.identity_id is distinct from identity_id or s.membership_id is distinct from membership_id or s.assignment_id is distinct from assignment_id
  or s.revoked_at is not null or s.expires_at<=clock_timestamp() or s.absolute_expires_at<=clock_timestamp()
  or not isfinite(s.expires_at) or not isfinite(s.absolute_expires_at) then raise exception 'Programplan denied' using errcode='42501'; end if;
 return s;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_subject_diagnostics(s jsonb, started_on text, block_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare result jsonb:='[]'; reason text; base jsonb:=jsonb_build_object('subjectCode',s->>'code','blockId',block_id);
begin
 if s->>'typeOfSyllabus'<>'GRADE_SUBJECT_SYLLABUS' then result:=result||jsonb_build_array(base||jsonb_build_object('code','unsupported_regime')); end if;
 if not (s->'schoolTypes' ? 'GY') then result:=result||jsonb_build_array(base||jsonb_build_object('code','unsupported_school_type')); end if;
 reason:=public.phase5_programplan_date_diagnostic(s,started_on);
 if reason is not null then result:=result||jsonb_build_array(base||jsonb_build_object('code',reason)); end if;
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_term_rows(reference jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare resolution jsonb; payload jsonb; program jsonb; orientation jsonb; block jsonb; subject jsonb; level jsonb; selected jsonb;
 rows jsonb:='[]'; part text; key text; group_subjects jsonb; position integer;
begin
 resolution:=public.phase5_resolve_programplan_basis(reference);
 if resolution->>'status' is distinct from 'resolved' then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
 select c.payload into payload from public.programplan_catalogs c where c.catalog_id=reference->>'catalogId';
 select value into program from jsonb_array_elements(payload->'programs') where value->>'code'=reference->'programRef'->>'code' and value->'version'=reference->'programRef'->'version';
 select value into orientation from jsonb_array_elements(program->'orientations') where value->>'code'=reference->>'orientationCode';
 foreach part in array array['foundation','programmeSpecific','orientation'] loop
  block:=case when part='orientation' then coalesce(orientation->'subjects','[]'::jsonb) else program->part end;
  for subject in select value from jsonb_array_elements(block) loop
   if subject->'optional'='false'::jsonb and subject->'subjectVersion'<>'null'::jsonb then
    for level in select value from jsonb_array_elements(subject->'levels') loop
     key:=part||':'||(subject->>'code')||':'||((subject->>'subjectVersion')::numeric::integer)::text||':'||(level->>'code');
     rows:=rows||jsonb_build_array(jsonb_build_object('key',key,'points',level->'points'));
    end loop;
   end if;
  end loop;
  if reference ? 'choiceBlocks' then
   for group_subjects in select value from jsonb_array_elements(public.phase5_programplan_alternative_groups(block)) loop
    for position in 0..jsonb_array_length(group_subjects->0->'levels')-1 loop
     select 'alternative:'||part||':'||string_agg((value->>'code')||':'||((value->>'subjectVersion')::integer)::text||':'||(value->'levels'->position->>'code'),'+' order by n)
      into key from jsonb_array_elements(group_subjects) with ordinality e(value,n);
     rows:=rows||jsonb_build_array(jsonb_build_object('key',key,'points',group_subjects->0->'levels'->position->'points'));
    end loop;
   end loop;
  end if;
 end loop;
 for selected in select value from jsonb_array_elements(reference->'specializationRefs') loop
  key:='specialization:'||(selected->>'subjectCode')||':'||((selected->>'subjectVersion')::numeric::integer)::text||':'||(selected->>'itemCode');
  rows:=rows||jsonb_build_array(jsonb_build_object('key',key,'points',selected->'points'));
 end loop;
 if not reference ? 'choiceBlocks' then return rows||'[{"key":"meta:individualChoice","points":200},{"key":"meta:diplomaWork","points":100}]'::jsonb; end if;
 for selected in select value from jsonb_array_elements(public.phase5_programplan_choice_blocks(reference)) loop
  rows:=rows||jsonb_build_array(jsonb_build_object('key',selected->'rowKey','points',selected->'points'));
 end loop;
 return rows||'[{"key":"meta:diplomaWork","points":100}]'::jsonb;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_terms_audit(plan_id uuid, operation text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.access_assignments; i public.identities; s public.app_sessions;
begin
 if operation is null or operation not in ('programplan_terms_read','programplan_terms_changed') then raise exception 'Invalid programplan operation' using errcode='22023'; end if;
 a:=public.phase5_programplan_actor(); s:=public.phase5_programplan_session_check(); perform public.phase5_programplan_scope(plan_id);
 select * into i from public.identities where id=s.identity_id;
 begin
  insert into public.security_events(correlation_id,source,actor_identity_id,actor_issuer,actor_subject,session_id,membership_id,assignment_id,customer_id,action,object_type,object_id,outcome,details)
  values(nullif(current_setting('app.correlation_id',true),'')::uuid,'db',i.id,i.issuer,i.subject,s.id,a.membership_id,a.id,a.customer_id,operation,'programplan',plan_id,'ok','{}'::jsonb);
 exception when others then raise exception 'Programplan audit unavailable' using errcode='55000'; end;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_terms_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
 if tg_op='UPDATE' and new.term_distribution is distinct from old.term_distribution then
  if old.status<>'utkast' then raise exception 'Programplan version locked' using errcode='42501'; end if;
  if new.revision<>old.revision+1 then raise exception 'Programplan revision required' using errcode='40001'; end if;
 end if;
 -- Basis edits cannot orphan an allocated level. Clear the row explicitly first.
 perform public.phase5_programplan_validate_terms(new.basis_reference,new.term_distribution);
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_unit(unit_id uuid, require_hm boolean DEFAULT false)
 RETURNS school_units
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.access_assignments; u public.school_units;
begin
 a:=public.phase5_programplan_actor();
 if require_hm and a.function<>'huvudman' then raise exception 'Education denied' using errcode='42501'; end if;
 select s.* into u from public.school_units s join public.organizers g on g.id=s.organizer_id and g.customer_id=a.customer_id
 join public.mandate_units m on m.assignment_id=a.id and m.unit_id=s.id
 where s.id=phase5_programplan_unit.unit_id and s.organizer_id=a.organizer_id
 and exists(select 1 from public.school_unit_types t where t.unit_id=s.id and t.school_type='GY') for update of s;
 if not found then raise exception 'Education denied' using errcode='42501'; end if;
 a:=public.phase5_programplan_actor();
 if (require_hm and a.function<>'huvudman') or not exists(select 1 from public.school_units s join public.organizers g on g.id=s.organizer_id and g.customer_id=a.customer_id
 join public.mandate_units m on m.assignment_id=a.id and m.unit_id=s.id where s.id=u.id and s.organizer_id=a.organizer_id
 and exists(select 1 from public.school_unit_types t where t.unit_id=s.id and t.school_type='GY')) then raise exception 'Education denied' using errcode='42501'; end if;
 select * into u from public.school_units where id=u.id; return u;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_unit_package_audit(plan_id uuid, operation text, unit_id uuid DEFAULT NULL::uuid, revision integer DEFAULT NULL::integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.access_assignments;s public.app_sessions;i public.identities;
begin
 if operation not in ('programplan_unit_packages_read','programplan_unit_packages_changed')
  or (operation='programplan_unit_packages_changed') is distinct from (unit_id is not null and revision is not null) then raise exception 'Invalid package audit' using errcode='22023';end if;
 a:=public.phase5_programplan_actor();s:=public.phase5_programplan_session_check();select * into i from public.identities where id=s.identity_id;
 begin
 insert into public.security_events(correlation_id,source,actor_identity_id,actor_issuer,actor_subject,session_id,membership_id,assignment_id,customer_id,action,object_type,object_id,outcome,details)
 values(nullif(current_setting('app.correlation_id',true),'')::uuid,'db',i.id,i.issuer,i.subject,s.id,a.membership_id,a.id,a.customer_id,operation,'programplan',plan_id,'ok',
 case when unit_id is null then '{}'::jsonb else jsonb_build_object('unitId',unit_id,'packageRevision',revision) end);
 exception when others then raise exception 'Package audit unavailable' using errcode='55000';end;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_upgrade_shape(reference jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare payload jsonb; program jsonb; orientation jsonb; subject jsonb; blocks jsonb:='[]';
begin
 if public.phase5_resolve_programplan_basis(reference)->>'status' is distinct from 'resolved' then raise exception 'Invalid programplan basis' using errcode='22023'; end if;
 if reference ? 'choiceBlocks' then return reference; end if;
 select c.payload into payload from public.programplan_catalogs c where c.catalog_id=reference->>'catalogId';
 select value into program from jsonb_array_elements(payload->'programs') where value->>'code'=reference->'programRef'->>'code';
 select value into orientation from jsonb_array_elements(program->'orientations') where value->>'code'=reference->>'orientationCode';
 for subject in select value from jsonb_array_elements(program->'programmeSpecific')
  union all select value from jsonb_array_elements(coalesce(orientation->'subjects','[]'::jsonb)) loop
  if subject->>'code' in ('MOSP','SPRK','NAVE') and jsonb_array_length(subject->'levels')=0 then
   blocks:=blocks||jsonb_build_array(jsonb_build_object('id',case subject->>'code' when 'MOSP' then 'mosp' when 'SPRK' then 'sprk' else 'nave' end,
    'kind',case subject->>'code' when 'MOSP' then 'modernLanguage' when 'SPRK' then 'languageSubject' else 'naturalScience' end,'points',subject->'points','name',subject->'name'));
  end if;
 end loop;
 return reference||jsonb_build_object('choiceBlocks',blocks||'[{"id":"iv1","kind":"individualChoice","points":200,"name":"Individuellt val"}]'::jsonb);
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_upgrade_terms(old_reference jsonb, old_distribution jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare reference jsonb; entry jsonb; result jsonb:='[]';
begin
 reference:=public.phase5_programplan_upgrade_shape(old_reference);
 perform public.phase5_programplan_validate_terms(old_reference,old_distribution);
 if old_reference ? 'choiceBlocks' then return old_distribution; end if;
 for entry in select value from jsonb_array_elements(old_distribution) loop
  result:=result||jsonb_build_array(case when entry->>'rowKey'='meta:individualChoice' then entry||jsonb_build_object('rowKey','block:iv1') else entry end);
 end loop;
 perform public.phase5_programplan_validate_terms(reference,result);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_url(v jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare authority text; host text; port text; address inet;
begin
 if not public.phase5_programplan_text(v,2000) or (v#>>'{}') !~ '^https?://' or (v#>>'{}') ~ '[[:space:]]' then return false; end if;
 authority:=substring(v#>>'{}' from '^https?://([^/?#]+)');
 if authority is null or authority ~ '@' then return false; end if;
 if left(authority,1)='[' then
  if authority !~ '^\[[0-9A-Fa-f:]+\](:[0-9]+)?$' then return false; end if;
  host:=substring(authority from '^\[([^]]+)\]');
  begin address:=host::inet; exception when invalid_text_representation then return false; end;
  if family(address)<>6 then return false; end if;
  port:=substring(authority from '\]:([0-9]+)$');
 else
  if authority !~ '^[[:alnum:]._-]+(:[0-9]+)?$' then return false; end if;
  port:=substring(authority from ':([0-9]+)$');
 end if;
 if port is not null and (length(port)>5 or port::integer>65535) then return false; end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_validate_basis(reference jsonb, offering offerings, previous_choices text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare resolution jsonb; choices text[];
begin
 resolution:=public.phase5_resolve_programplan_basis(reference);
 if resolution->>'status' is distinct from 'resolved' or reference->'programRef'->>'code' is distinct from offering.program_code
  or reference->>'orientationCode' is distinct from offering.orientation_code then raise exception 'Invalid programplan basis' using errcode='22023'; end if;
 select coalesce(array_agg(value->>'itemCode' order by n),'{}'::text[]) into choices from jsonb_array_elements(reference->'specializationRefs') with ordinality e(value,n);
 if previous_choices is not null and choices is distinct from previous_choices then raise exception 'Legacy choices mismatch' using errcode='22023'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_validate_scoped_selection(reference jsonb, block_id text, entry jsonb, unit_id uuid, organizer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare r jsonb;p public.programplan_packages;
begin
 r:=public.phase5_programplan_validate_selection(reference,block_id,entry);
 if entry->'ref'->>'type'='package' then
  select * into p from public.programplan_packages x where x.package_id=(entry->'ref'->>'packageId')::uuid and x.version=(entry->'ref'->>'version')::integer;
  if p.organizer_id is distinct from organizer_id or (p.unit_id is not null and p.unit_id is distinct from unit_id) then raise exception 'Package school denied' using errcode='42501';end if;
 end if;
 return r;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_validate_selection(reference jsonb, block_id text, entry jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare b jsonb; r jsonb; payload jsonb; l jsonb; subject jsonb; item jsonb; ladder jsonb; start_index integer;
 step jsonb; n integer; total integer:=0; key text; keys text[]:='{}'; d jsonb; v jsonb; allocated integer; resolution jsonb;original_ref jsonb;pkg public.programplan_packages;package_key text;
begin
 perform public.phase5_programplan_require_current_shape(reference);
 resolution:=public.phase5_resolve_programplan_basis(reference);
 if resolution->>'status' is distinct from 'resolved' then raise exception 'Invalid package selection' using errcode='22023';end if;
 select value into b from jsonb_array_elements(reference->'choiceBlocks') where value->>'id'=block_id;
 if b is null or not public.phase5_programplan_shape(entry,array['ref','distribution'])
  or not public.phase5_programplan_array(entry->'distribution',200) then raise exception 'Invalid package selection' using errcode='22023';end if;
 r:=entry->'ref';original_ref:=r;
 if r->>'type'='package' then
  if not public.phase5_programplan_shape(r,array['type','packageId','version']) or jsonb_typeof(r->'packageId') is distinct from 'string'
   or r->>'packageId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' or not public.phase5_programplan_integer(r->'version',1,2147483647) then raise exception 'Invalid package reference' using errcode='22023';end if;
  select * into pkg from public.programplan_packages x where x.package_id=(r->>'packageId')::uuid and x.version=(r->>'version')::integer;
  if not found or pkg.catalog_id is distinct from reference->>'catalogId' or pkg.kind is distinct from b->>'kind' then raise exception 'Invalid block package kind or catalog' using errcode='22023';end if;
  perform public.phase5_programplan_package_levels(pkg.catalog_id,pkg.kind,pkg.levels);
  package_key:='package:'||pkg.package_id::text||'@'||pkg.version::text;
  r:=jsonb_build_object('levels',pkg.levels);
 else
 if not public.phase5_programplan_shape(r,array['type','languageCode','levels']) or r->>'type' is distinct from 'language'
  or jsonb_typeof(r->'languageCode') not in ('null','string') or not public.phase5_programplan_array(r->'levels',7)
  or jsonb_array_length(r->'levels')=0 then raise exception 'Invalid language package' using errcode='22023';end if;
 if r->>'languageCode' is not null and not exists(select 1 from jsonb_array_elements(public.phase5_programplan_languages()) lang where lang->>'code'=r->>'languageCode') then
  raise exception 'Invalid language code' using errcode='22023';end if;
 -- Exactly one contiguous ladder, preserving supplied level order.
 for ladder in select value from jsonb_array_elements(public.phase5_programplan_ladders()) loop
  select ordinality::integer into start_index from jsonb_array_elements(ladder->'steps') with ordinality e(value,ordinality)
   where value->>'subjectCode'=r->'levels'->0->>'subjectCode' and value->>'itemCode'=r->'levels'->0->>'itemCode';
  if start_index is not null then exit;end if;
 end loop;
 if start_index is null or start_index+jsonb_array_length(r->'levels')-1>jsonb_array_length(ladder->'steps')
  or ((ladder->>'languageRequired')::boolean and r->>'languageCode' is null)
  or (not (ladder->>'languageRequired')::boolean and r->>'languageCode' is not null)
  or (ladder->>'languageCode' is not null and ladder->>'languageCode' is distinct from r->>'languageCode') then
  raise exception 'Invalid language ladder' using errcode='22023';end if;
 end if;
 select c.payload into payload from public.programplan_catalogs c where c.catalog_id=reference->>'catalogId';
 n:=0;
 for l in select value from jsonb_array_elements(r->'levels') loop
  if package_key is null then step:=ladder->'steps'->(start_index+n-1);end if;n:=n+1;
  if not public.phase5_programplan_shape(l,array['subjectCode','subjectVersion','itemCode','points'])
   or not public.phase5_programplan_integer(l->'subjectVersion',1,100000)
   or (package_key is null and (l->>'subjectCode' is distinct from step->>'subjectCode' or l->>'itemCode' is distinct from step->>'itemCode')) then raise exception 'Invalid language level' using errcode='22023';end if;
  select value into subject from jsonb_array_elements(payload->'subjects') where value->>'code'=l->>'subjectCode' and value->'version'=l->'subjectVersion';
  select value into item from jsonb_array_elements(coalesce(subject->'items','[]'::jsonb)) where value->>'code'=l->>'itemCode';
  if subject is null or item is null or item->'points' is distinct from l->'points'
   or not (subject->'schoolTypes' ? 'GY') or subject->>'typeOfSyllabus' is distinct from 'GRADE_SUBJECT_SYLLABUS'
   or subject->>'startDate' is null or subject->>'startDate'>reference->>'startedOn'
   or (subject->>'endDate' is not null and subject->>'endDate'<reference->>'startedOn')
   or (subject->>'canceledDate' is not null and subject->>'canceledDate'<=reference->>'startedOn') then raise exception 'Invalid language level' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(public.phase5_programplan_term_rows(reference)) fixed
   where (fixed->>'key' not like 'block:%' and fixed->>'key' not like 'meta:%' and fixed->>'key' not like 'alternative:%'
    and substring(fixed->>'key' from position(':' in fixed->>'key')+1)=(l->>'subjectCode')||':'||(l->>'subjectVersion')||':'||(l->>'itemCode'))
    or (fixed->>'key' like 'alternative:%' and exists(select 1 from regexp_split_to_table(substring(fixed->>'key' from '^alternative:[^:]+:(.*)$'),'\+') alternative_key
     where alternative_key=(l->>'subjectCode')||':'||(l->>'subjectVersion')||':'||(l->>'itemCode')))) then
   raise exception 'Package level already fixed' using errcode='22023';end if;
  if package_key is null and b->>'kind'='naturalScience' then raise exception 'Invalid block package kind' using errcode='22023';end if;
  if b->>'kind'='specialization' and not exists(select 1 from jsonb_array_elements(payload->'programs') program cross join lateral jsonb_array_elements(program->'specialization') opt cross join lateral jsonb_array_elements(opt->'levels') level
   where program->>'code'=reference->'programRef'->>'code' and program->'version'=reference->'programRef'->'version'
   and opt->>'code'=l->>'subjectCode' and opt->'subjectVersion'=l->'subjectVersion' and level->>'code'=l->>'itemCode' and level->'points'=l->'points') then
   raise exception 'Invalid block package level' using errcode='22023';end if;
  key:=(l->>'subjectCode')||':'||(l->>'subjectVersion')||':'||(l->>'itemCode'); keys:=array_append(keys,key);total:=total+(l->>'points')::integer;
 end loop;
 if total is distinct from (b->>'points')::integer then raise exception 'Package points differ from block' using errcode='22023';end if;
 keys:='{}';
 for d in select value from jsonb_array_elements(entry->'distribution') loop
  if not public.phase5_programplan_shape(d,array['levelKey','points']) or jsonb_typeof(d->'levelKey') is distinct from 'string'
   or not public.phase5_programplan_array(d->'points',6) or jsonb_array_length(d->'points')<>6 then raise exception 'Invalid package distribution' using errcode='22023';end if;
  key:=d->>'levelKey';
  if key=any(keys) then raise exception 'Duplicate package distribution' using errcode='22023';end if;keys:=array_append(keys,key);
  select value into l from jsonb_array_elements(r->'levels') lev(value) where (value->>'subjectCode')||':'||(value->>'subjectVersion')||':'||(value->>'itemCode')=key;
  if l is null then raise exception 'Unknown package level row' using errcode='22023';end if;
  allocated:=0;
  for v in select value from jsonb_array_elements(d->'points') loop
   if not public.phase5_programplan_integer(v,0,10000) then raise exception 'Invalid package points' using errcode='22023';end if;allocated:=allocated+(v#>>'{}')::integer;
  end loop;
  if allocated>(l->>'points')::integer then raise exception 'Package allocation exceeds level' using errcode='22023';end if;
 end loop;
 return jsonb_build_object('key',coalesce(package_key,'language:'||coalesce(r->>'languageCode','-')||':'||(select string_agg(lvl->>'itemCode','+' order by ordinality) from jsonb_array_elements(r->'levels') with ordinality e(lvl,ordinality))),
 'ref',original_ref,'levels',r->'levels','points',total,'distribution',entry->'distribution');
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_validate_terms(reference jsonb, distribution jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare rows jsonb; entry jsonb; cell jsonb; allowed jsonb; seen text[]:='{}'; key text; total integer;
begin
 if not public.phase5_programplan_array(distribution,2000) then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
 -- Legacy plans can carry only the empty distribution until explicitly bound.
 if reference is null then
  if distribution<>'[]'::jsonb then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
  return;
 end if;
 rows:=public.phase5_programplan_term_rows(reference);
 for entry in select value from jsonb_array_elements(distribution) loop
  if not public.phase5_programplan_shape(entry,array['rowKey','points']) or not public.phase5_programplan_text(entry->'rowKey',320)
   or not public.phase5_programplan_array(entry->'points',6) then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
  if jsonb_array_length(entry->'points')<>6 then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
  key:=entry->>'rowKey';
  if key=any(seen) then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
  seen:=array_append(seen,key);
  select value into allowed from jsonb_array_elements(rows) where value->>'key'=key;
  if not found then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
  total:=0;
  for cell in select value from jsonb_array_elements(entry->'points') loop
   if not public.phase5_programplan_integer(cell,0,10000) then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
   total:=total+(cell#>>'{}')::integer;
  end loop;
  if total>(allowed->>'points')::integer then raise exception 'Invalid programplan terms' using errcode='22023'; end if;
 end loop;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_workspace(offering_id uuid, version_page integer, catalog_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare o public.offerings; result jsonb; catalog_payload jsonb; catalog_status text; catalog_diagnostic text;
begin
 o:=public.phase5_programplan_scope(null,offering_id);
 if version_page is null or version_page not between 1 and 100000
  or (catalog_id is not null and catalog_id !~ '^sha256:[0-9a-f]{64}$') then
  raise exception 'Invalid programplan workspace request' using errcode='22023'; end if;
 catalog_status:='unselected';
 if catalog_id is not null then
  select c.payload into catalog_payload from public.programplan_catalogs c where c.catalog_id=phase5_programplan_workspace.catalog_id;
  if found then catalog_status:='selected';
  else catalog_status:='blocked'; catalog_diagnostic:='catalog_unavailable'; end if;
 end if;
 with scoped_versions as materialized (
  select p.* from public.point_plans p where p.offering_id=o.id and p.organizer_id=o.organizer_id
 ), page_rows as (
  select * from scoped_versions order by version desc,id limit 50 offset (version_page-1)*50
 )
 select jsonb_build_object('education',public.phase5_programplan_education(o),'lifecycle',public.phase5_programplan_lifecycle(o),
  'versions',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'version',p.version,'revision',p.revision,'status',p.status,
   'decidedOn',p.decided_on,'catalogId',p.catalog_id,'basisReference',p.basis_reference,
   'legacySpecialization',case when p.catalog_id is null then to_jsonb(p.specialization) else null end) order by p.version desc,p.id)
   from page_rows p),'[]'::jsonb),
  'versionCount',(select count(*) from scoped_versions),'versionPage',version_page,'pageSize',50,
  'catalogs',coalesce((select jsonb_agg(jsonb_build_object('catalogId',c.catalog_id,'source',c.payload->'source') order by c.catalog_id)
   from public.programplan_catalogs c),'[]'::jsonb),
  'catalog',jsonb_build_object('status',catalog_status,'catalogId',catalog_id,'diagnostic',catalog_diagnostic,'payload',catalog_payload),
  'decisionReady',false) into result;
 perform public.phase5_programplan_scope(null,o.id);
 perform public.phase5_programplan_workspace_audit(o.id,'programplan_workspace_read');
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_workspace_audit(offering_id uuid, operation text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.access_assignments; s public.app_sessions; i public.identities;
begin
 if operation is null or operation not in ('programplan_offerings_listed','programplan_workspace_read')
  or (operation='programplan_offerings_listed') is distinct from (offering_id is null) then
  raise exception 'Invalid programplan workspace operation' using errcode='22023'; end if;
 a:=public.phase5_programplan_actor();
 if offering_id is not null then perform public.phase5_programplan_scope(null,offering_id); end if;
 s:=public.phase5_programplan_session_check();
 select * into i from public.identities where id=s.identity_id;
 begin
  insert into public.security_events(correlation_id,source,actor_identity_id,actor_issuer,actor_subject,session_id,membership_id,assignment_id,customer_id,
   action,object_type,object_id,outcome,details)
  values(nullif(current_setting('app.correlation_id',true),'')::uuid,'db',i.id,i.issuer,i.subject,s.id,a.membership_id,a.id,a.customer_id,
   operation,case when offering_id is null then 'education_collection' else 'education' end,offering_id,'ok','{}');
 exception when others then raise exception 'Programplan workspace audit unavailable' using errcode='55000'; end;
end $function$

CREATE OR REPLACE FUNCTION public.phase5_programplan_writable(o offerings, require_hm boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.access_assignments; fresh public.offerings;
begin
 a:=public.phase5_programplan_actor();
 select * into fresh from public.offerings where id=o.id;
 if not found or a.function='administrator' or (require_hm and a.function<>'huvudman') or fresh.organizer_id<>a.organizer_id
 or not exists(select 1 from public.offering_units ou where ou.offering_id=fresh.id and ou.unit_id=fresh.unit_id and ou.organizer_id=fresh.organizer_id)
 or exists(select 1 from public.offering_units ou where ou.offering_id=fresh.id and not exists(select 1 from public.mandate_units m where m.assignment_id=a.id and m.unit_id=ou.unit_id)) then
  raise exception 'Programplan denied' using errcode='42501',hint='programplan_mandate'; end if;
 if fresh.archived_at is not null then raise exception 'Programplan archived' using errcode='42501',hint='programplan_archived'; end if;
 if public.phase5_programplan_phase(fresh) is distinct from 'framtida' then raise exception 'Programplan started' using errcode='42501',hint='programplan_started'; end if;
end $function$

