-- Intern kedjeprövning, INTE ett fullständigt behörighetsbeslut.
-- Fortsatt stängd: inga GRANT, ingen inkoppling i assignment_is_valid.
-- Staff-bindning, objekt-/professionsscope, session och mutationslås måste
-- fortfarande prövas av den kommande kompletta mandatvägen.
create function public.phase3_mandate_chain_is_valid(assignment_id uuid)
returns boolean language plpgsql stable security invoker
set search_path = pg_catalog, public as $$
declare
  child public.access_assignments;
  parent public.access_assignments;
  cursor_id uuid := assignment_id;
  seen uuid[] := '{}';
  today date := (statement_timestamp() at time zone 'Europe/Stockholm')::date;
begin
  loop
    if cursor_id is null or cursor_id = any(seen) or cardinality(seen) >= 64 then return false; end if;
    seen := array_append(seen, cursor_id);
    select * into child from public.access_assignments where id = cursor_id;
    if not found then return false; end if;
    if child.profile_id is distinct from 'synthetic-v1' or child.ended_at is not null
       or child.valid_from > today or (child.valid_to is not null and child.valid_to < today)
       or (child.starts_at is not null and statement_timestamp() < child.starts_at)
       or (child.ends_at is not null and statement_timestamp() >= child.ends_at)
       or not exists (select 1 from public.memberships m join public.customers c on c.id=m.customer_id
         where m.id=child.membership_id and m.customer_id=child.customer_id and m.status='active' and c.closed_at is null)
       or not exists (select 1 from public.mandate_units u where u.assignment_id=child.id)
    then return false; end if;
    if child.parent_assignment_id is null then
      -- Elevhälsoansvarig förseedas; offentlig utnämning ingår inte.
      return child.function in ('huvudman','elevhalsoansvarig','it');
    end if;
    select * into parent from public.access_assignments where id=child.parent_assignment_id;
    if not found then return false; end if;
    if parent.customer_id is distinct from child.customer_id
       or parent.organizer_id is distinct from child.organizer_id
       or not ((parent.function='huvudman' and child.function='rektor')
         or (parent.function='rektor' and child.function in ('larare','administrator','elevhalsa','support'))
         or (parent.function='elevhalsoansvarig' and child.function='elevhalsa'))
       or exists (select 1 from public.memberships a join public.memberships b on a.identity_id=b.identity_id
         where a.id=child.membership_id and b.id=parent.membership_id)
       or child.valid_from < parent.valid_from
       or (parent.valid_to is not null and (child.valid_to is null or child.valid_to > parent.valid_to))
       or (parent.starts_at is not null and (child.starts_at is null or child.starts_at < parent.starts_at))
       or (parent.ends_at is not null and (child.ends_at is null or child.ends_at > parent.ends_at))
       or exists (select 1 from public.mandate_units cu where cu.assignment_id=child.id
         and not exists (select 1 from public.mandate_units pu
           where pu.assignment_id=parent.id and pu.unit_id=cu.unit_id and pu.customer_id=cu.customer_id))
    then return false; end if;
    cursor_id := parent.id;
  end loop;
end $$

-- Komplett intern form-/kedjeprövning och objekturval. Fortsatt utan Worker-GRANT.
create function public.phase3_mandate_shape(a public.access_assignments)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare units integer; groups integer; pupils integer; cases integer;
begin
  if a.profile_id is distinct from 'synthetic-v1' or a.scope_kind is null then return false; end if;
  select count(*) into units from public.mandate_units where assignment_id=a.id;
  select count(*) into groups from public.mandate_groups where assignment_id=a.id;
  select count(*) into pupils from public.mandate_pupils where assignment_id=a.id;
  select count(*) into cases from public.mandate_cases where assignment_id=a.id;
  if a.function in ('kundadmin','granskare') then
    return a.organizer_id is null and a.scope_kind='school' and units+groups+pupils+cases=0;
  end if;
  if units=0 or a.organizer_id is null then return false; end if;
  if a.function='larare' then return a.scope_kind='group' and groups>0 and pupils+cases=0; end if;
  if a.function='support' then
    return a.scope_kind='pupil' and units=1 and pupils=1 and groups+cases=0
      and a.parent_assignment_id is not null and a.approved_by_assignment_id=a.parent_assignment_id
      and a.starts_at is not null and a.ends_at is not null
      and a.ends_at-a.starts_at <= interval '60 minutes'
      and a.purpose_code='synthetic-troubleshooting';
  end if;
  if a.function='elevhalsa' then
    return (a.scope_kind='school' and groups+pupils+cases=0)
      or (a.scope_kind='pupil' and pupils>0 and groups+cases=0)
      or (a.scope_kind='case' and cases>0 and groups+pupils=0);
  end if;
  return a.scope_kind='school' and groups+pupils+cases=0;
end $$

create function public.phase3_mandate_is_valid(assignment_id uuid, require_current boolean default true)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare a public.access_assignments; p public.access_assignments;
  cursor_id uuid:=assignment_id; seen uuid[]:='{}'; check_time boolean:=require_current;
  today date:=(statement_timestamp() at time zone 'Europe/Stockholm')::date;
begin
  loop
    if cursor_id is null or cursor_id=any(seen) or cardinality(seen)>=64 then return false; end if;
    seen:=array_append(seen,cursor_id);
    select * into a from public.access_assignments where id=cursor_id;
    if not found or a.ended_at is not null then return false; end if;
    -- Tidigare kundkonton behålls; äldre verksamhetsmandat ger ingen fas3-rätt.
    if a.profile_id is null then
      return a.function in ('kundadmin','granskare') and a.parent_assignment_id is null
        and a.valid_from<=today and (a.valid_to is null or today<=a.valid_to)
        and exists(select 1 from public.memberships m join public.customers c on c.id=m.customer_id
          where m.id=a.membership_id and m.status='active' and c.closed_at is null);
    end if;
    if not public.phase3_mandate_shape(a)
      or not exists(select 1 from public.memberships m join public.customers c on c.id=m.customer_id
        where m.id=a.membership_id and m.status='active' and c.closed_at is null)
      or (a.function in ('rektor','larare') and not public.phase3_staff_binding_is_valid(a.id))
      or (check_time and (a.valid_from>today or (a.valid_to is not null and a.valid_to<today)
        or (a.starts_at is not null and a.starts_at>statement_timestamp())
        or (a.ends_at is not null and a.ends_at<=statement_timestamp()))) then return false; end if;
    if a.parent_assignment_id is null then
      return a.function in ('huvudman','elevhalsoansvarig','it','kundadmin','granskare');
    end if;
    select * into p from public.access_assignments where id=a.parent_assignment_id;
    if not found then return false; end if;
    if a.issued_by_assignment_id is distinct from p.id
      or a.customer_id is distinct from p.customer_id or a.organizer_id is distinct from p.organizer_id
      or not ((p.function='huvudman' and a.function='rektor')
        or (p.function='rektor' and a.function in ('larare','administrator','elevhalsa','support'))
        or (p.function='elevhalsoansvarig' and a.function='elevhalsa')
        or (p.function='kundadmin' and a.function in ('kundadmin','granskare')))
      or exists(select 1 from public.memberships x join public.memberships y on x.identity_id=y.identity_id
        where x.id=a.membership_id and y.id=p.membership_id)
      or a.valid_from<p.valid_from or (p.valid_to is not null and (a.valid_to is null or a.valid_to>p.valid_to))
      or (p.starts_at is not null and (a.starts_at is null or a.starts_at<p.starts_at))
      or (p.ends_at is not null and (a.ends_at is null or a.ends_at>p.ends_at))
      or exists(select 1 from public.mandate_units u where u.assignment_id=a.id
        and not exists(select 1 from public.mandate_units pu where pu.assignment_id=p.id and pu.unit_id=u.unit_id))
    then return false; end if;
    cursor_id:=p.id; check_time:=true;
  end loop;
end $$

create function public.phase3_actor() returns public.access_assignments
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments;
begin
  perform public.phase3_lock_customer(public.current_customer_id());
  select * into a from public.access_assignments where id=public.current_assignment_id();
  if not found or a.customer_id is distinct from public.current_customer_id()
    or a.membership_id is distinct from nullif(current_setting('app.membership_id',true),'')::uuid
    or not exists(select 1 from public.memberships m where m.id=a.membership_id and m.identity_id=public.current_identity_id())
    or not public.phase3_mandate_is_valid(a.id) then
    raise exception 'Mandate denied' using errcode='42501';
  end if;
  return a;
end $$

create function public.phase3_read_pupils(pupil_id uuid default null, case_id uuid default null, for_export boolean default false)
returns table(id uuid,display_name text,unit_id uuid,group_ids uuid[])
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments;
begin
  a:=public.phase3_actor();
  if a.function not in ('rektor','larare','administrator','elevhalsa','support')
    or (for_export and a.function<>'administrator') then raise exception 'Read denied' using errcode='42501'; end if;
  return query select p.id,p.display_name,p.unit_id,
    array(select gm.group_id from public.phase3_probe_group_members gm where gm.pupil_id=p.id
      and (a.scope_kind<>'group' or exists(select 1 from public.mandate_groups g where g.assignment_id=a.id and g.group_id=gm.group_id)) order by gm.group_id)
  from public.phase3_probe_pupils p where (pupil_id is null or p.id=pupil_id)
    and public.phase3_pupil_in_scope(a.id,p.id,case_id) order by p.id;
end $$

revoke all on function public.phase3_mandate_shape(public.access_assignments),
  public.phase3_mandate_is_valid(uuid,boolean),public.phase3_lock_customer(uuid),public.phase3_actor(),
  public.phase3_pupil_in_scope(uuid,uuid,uuid),public.phase3_read_pupils(uuid,uuid,boolean)
from public,anon,authenticated,skolplattform_worker

-- Kontrollerade mutationer förbereds stängda. Audit/CSRF/MFA sker i samma
-- servertransaktion; senare cutover återkallar äldre generella skrivprivilegier.
create function public.phase3_insert_mandate(actor_id uuid,payload jsonb) returns uuid
language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare parent public.access_assignments; recipient public.memberships; new_id uuid:=gen_random_uuid();
  fn public.access_function; unit_ids uuid[]; staff_id uuid; group_item jsonb; item uuid;
begin
  if jsonb_typeof(payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(payload) k
    where k not in ('membershipId','function','unitIds','scopeKind','groups','pupilIds','caseIds',
      'validFrom','validTo','startsAt','endsAt','profession','purposeCode','staffAssignmentId')) then
    raise exception 'Invalid mandate payload' using errcode='22023'; end if;
  select * into parent from public.access_assignments where id=actor_id;
  if not found or not public.phase3_mandate_is_valid(parent.id) then raise exception 'Mandate denied' using errcode='42501'; end if;
  select * into recipient from public.memberships where id=(payload->>'membershipId')::uuid and customer_id=parent.customer_id and status='active';
  if not found then raise exception 'Recipient denied' using errcode='42501'; end if;
  fn:=(payload->>'function')::public.access_function;
  unit_ids:=array(select jsonb_array_elements_text(coalesce(payload->'unitIds','[]'))::uuid);
  staff_id:=nullif(payload->>'staffAssignmentId','')::uuid;
  if fn in ('rektor','larare') then
    if staff_id is null then
      insert into public.assignments(organizer_id,name,role)
      select parent.organizer_id,coalesce(nullif(i.display_name,''),'Personal'),fn::text::public.staff_role
        from public.identities i where i.id=recipient.identity_id returning id into staff_id;
    else
      if not exists(select 1 from public.assignments s where s.id=staff_id and s.organizer_id=parent.organizer_id and s.role::text=fn::text)
        or exists(select 1 from public.staff_assignment_bindings b where b.staff_assignment_id=staff_id and b.membership_id<>recipient.id)
      then raise exception 'Staff binding denied' using errcode='42501'; end if;
    end if;
    insert into public.staff_assignment_bindings values(staff_id,recipient.id,parent.customer_id,parent.organizer_id) on conflict do nothing;
    insert into public.assignment_units(assignment_id,unit_id) select staff_id,unnest(unit_ids) on conflict do nothing;
  elsif staff_id is not null then raise exception 'Unexpected staff binding' using errcode='22023'; end if;
  insert into public.access_assignments(id,membership_id,customer_id,organizer_id,unit_id,function,
    valid_from,valid_to,staff_assignment_id,created_by,parent_assignment_id,issued_by_assignment_id,
    profile_id,scope_kind,profession,starts_at,ends_at,approved_by_assignment_id,purpose_code)
  values(new_id,recipient.id,parent.customer_id,parent.organizer_id,unit_ids[1],fn,
    coalesce((payload->>'validFrom')::date,public.app_today()),(payload->>'validTo')::date,staff_id,parent.membership_id,
    parent.id,parent.id,'synthetic-v1',payload->>'scopeKind',payload->>'profession',
    (payload->>'startsAt')::timestamptz,(payload->>'endsAt')::timestamptz,
    case when fn='support' then parent.id end,payload->>'purposeCode');
  insert into public.mandate_units select new_id,parent.customer_id,parent.organizer_id,unnest(unit_ids);
  for group_item in select value from jsonb_array_elements(coalesce(payload->'groups','[]')) loop
    if jsonb_typeof(group_item) is distinct from 'object' or exists(select 1 from jsonb_object_keys(group_item) k where k not in ('id','kind'))
      or group_item->>'kind' not in ('teaching','mentor') or group_item->>'kind' is null then
      raise exception 'Invalid group' using errcode='22023'; end if;
    insert into public.mandate_groups
      select new_id,g.id,parent.customer_id,g.unit_id,case group_item->>'kind' when 'teaching' then 'undervisning' else 'mentor' end
      from public.phase3_probe_groups g where g.id=(group_item->>'id')::uuid and g.customer_id=parent.customer_id;
    if not found then raise exception 'Group denied' using errcode='42501'; end if;
  end loop;
  for item in select jsonb_array_elements_text(coalesce(payload->'pupilIds','[]'))::uuid loop
    insert into public.mandate_pupils select new_id,p.id,parent.customer_id,p.unit_id from public.phase3_probe_pupils p where p.id=item and p.customer_id=parent.customer_id;
    if not found then raise exception 'Pupil denied' using errcode='42501'; end if;
  end loop;
  for item in select jsonb_array_elements_text(coalesce(payload->'caseIds','[]'))::uuid loop
    insert into public.mandate_cases select new_id,c.id,parent.customer_id,c.unit_id from public.phase3_probe_cases c where c.id=item and c.customer_id=parent.customer_id;
    if not found then raise exception 'Case denied' using errcode='42501'; end if;
  end loop;
  if not public.phase3_mandate_is_valid(new_id,false) then raise exception 'Delegation denied' using errcode='42501'; end if;
  return new_id;
end $$

create function public.phase3_grant_mandate(payload jsonb) returns uuid
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments;
begin
  a:=public.phase3_actor();
  return public.phase3_insert_mandate(a.id,payload);
end $$

create function public.phase3_revoke_mandate(target_id uuid) returns uuid
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; target public.access_assignments;
begin
  a:=public.phase3_actor();
  select * into target from public.access_assignments where id=target_id;
  if not found or target.parent_assignment_id is distinct from a.id or not public.phase3_mandate_is_valid(target.id,false) then
    raise exception 'Revocation denied' using errcode='42501'; end if;
  update public.access_assignments set ended_at=clock_timestamp(),ended_by=a.membership_id where id=target.id;
  return target.id;
end $$

create function public.phase3_mandate_context() returns jsonb
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; node uuid; ancestors jsonb:='[]';
begin
  a:=public.phase3_actor(); node:=a.parent_assignment_id;
  while node is not null loop
    ancestors:=ancestors||jsonb_build_array(public.phase3_assignment_document(node));
    select parent_assignment_id into node from public.access_assignments where id=node;
  end loop;
  return jsonb_build_object('assignment',public.phase3_assignment_document(a.id),'ancestors',ancestors,'serverNow',clock_timestamp());
end $$

create function public.phase3_list_mandates() returns jsonb
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; result jsonb;
begin
  a:=public.phase3_actor();
  select coalesce(jsonb_agg(public.phase3_assignment_document(t.id) order by t.id),'[]') into result
    from public.access_assignments t where t.parent_assignment_id=a.id and public.phase3_mandate_is_valid(t.id,false);
  return result;
end $$

revoke all on function public.phase3_insert_mandate(uuid,jsonb),public.phase3_grant_mandate(jsonb),
  public.phase3_revoke_mandate(uuid),public.phase3_assignment_document(uuid),
  public.phase3_mandate_context(),public.phase3_list_mandates()
from public,anon,authenticated,skolplattform_worker

-- Prövar verkliga integritets-/delegationsregler, men lämnar inga identiteter,
-- medlemskap, personalrader eller mandat från förhandsprövningen efter sig.
create function public.phase3_validate_invitation(actor_id uuid,issuer text,subject text,mandates jsonb)
returns jsonb language plpgsql volatile security invoker set search_path=pg_catalog,public as $$
declare chosen_identity uuid; member_id uuid; customer uuid; p jsonb; normalized jsonb:='[]';
begin
  if jsonb_typeof(mandates) is distinct from 'array' or jsonb_array_length(mandates) not between 1 and 10 then
    raise exception 'Invalid invitation mandates' using errcode='22023'; end if;
  select customer_id into customer from public.access_assignments where id=actor_id;
  begin
    select id into chosen_identity from public.identities i where i.issuer=$2 and i.subject=$3;
    if chosen_identity is null then insert into public.identities(issuer,subject) values($2,$3) returning id into chosen_identity; end if;
    insert into public.memberships(identity_id,customer_id) values(chosen_identity,customer)
      on conflict(identity_id,customer_id) do update set status=public.memberships.status returning id into member_id;
    for p in select value from jsonb_array_elements(mandates) loop
      if p ? 'membershipId' then raise exception 'Recipient must be identity-bound' using errcode='22023'; end if;
      p:=p||jsonb_build_object('validFrom',coalesce(p->>'validFrom',public.app_today()::text));
      perform public.phase3_insert_mandate(actor_id,p||jsonb_build_object('membershipId',member_id));
      normalized:=normalized||jsonb_build_array(p);
    end loop;
    raise exception 'Preview complete' using errcode='PT001';
  exception when sqlstate 'PT001' then return normalized;
  end;
end $$

create function public.phase3_issue_invitation(payload jsonb) returns uuid
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; normalized jsonb; result uuid; expiry timestamptz;
begin
  a:=public.phase3_actor();
  if jsonb_typeof(payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(payload) k
    where k not in ('personName','expectedIssuer','expectedSubject','expectedEmail','tokenHashHex','expiresAt','mandates')) then
    raise exception 'Invalid invitation payload' using errcode='22023'; end if;
  expiry:=(payload->>'expiresAt')::timestamptz;
  if expiry is null or not isfinite(expiry) or expiry<=clock_timestamp() or expiry>clock_timestamp()+interval '7 days' then
    raise exception 'Invalid invitation expiry' using errcode='22023'; end if;
  normalized:=public.phase3_validate_invitation(a.id,payload->>'expectedIssuer',payload->>'expectedSubject',payload->'mandates');
  insert into public.invitations(customer_id,token_hash,invited_person_name,expected_issuer,expected_subject,
    expected_email,grants,issued_by,expires_at,issued_by_assignment_id,mandate_payload)
  values(a.customer_id,decode(payload->>'tokenHashHex','hex'),payload->>'personName',payload->>'expectedIssuer',payload->>'expectedSubject',
    payload->>'expectedEmail',(select jsonb_agg(jsonb_build_object('function',p->>'function')) from jsonb_array_elements(normalized) p),
    a.membership_id::text,expiry,a.id,jsonb_build_object('version',1,'mandates',normalized)) returning id into result;
  return result;
end $$

create function public.phase3_redeem_invitation(token_hash bytea,session_id uuid) returns jsonb
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare s public.app_sessions; ident public.identities; invite public.invitations;
  member public.memberships; c public.customers; p jsonb; new_id uuid; assignments jsonb:='[]';
begin
  select * into s from public.app_sessions where id=$2 for update;
  if not found or s.identity_id is distinct from public.current_identity_id() or s.revoked_at is not null
    or s.expires_at<=clock_timestamp() or s.absolute_expires_at<=clock_timestamp() then
    raise exception 'Invitation denied' using errcode='42501'; end if;
  select * into ident from public.identities where id=s.identity_id;
  select * into invite from public.invitations i where i.token_hash=$1;
  if not found then raise exception 'Invitation denied' using errcode='42501'; end if;
  perform public.phase3_lock_customer(invite.customer_id);
  select * into invite from public.invitations where id=invite.id for update;
  if invite.used_at is not null or invite.expires_at<=clock_timestamp()
    or invite.expected_issuer is distinct from ident.issuer or invite.expected_subject is distinct from ident.subject then
    raise exception 'Invitation denied' using errcode='42501'; end if;
  select * into c from public.customers where id=invite.customer_id and closed_at is null;
  if not found then raise exception 'Invitation denied' using errcode='42501'; end if;
  insert into public.memberships(identity_id,customer_id) values(ident.id,c.id)
    on conflict(identity_id,customer_id) do update set status=public.memberships.status returning * into member;
  if member.status<>'active' then raise exception 'Invitation denied' using errcode='42501'; end if;
  if invite.issued_by_assignment_id is not null then
    if invite.mandate_payload->>'version' is distinct from '1' or not public.phase3_mandate_is_valid(invite.issued_by_assignment_id) then
      raise exception 'Invitation issuer denied' using errcode='42501'; end if;
    for p in select value from jsonb_array_elements(invite.mandate_payload->'mandates') loop
      new_id:=public.phase3_insert_mandate(invite.issued_by_assignment_id,p||jsonb_build_object('membershipId',member.id));
      assignments:=assignments||jsonb_build_array(jsonb_build_object('id',new_id,'function',p->>'function'));
    end loop;
  elsif invite.issued_by='leverantor:cli' and invite.mandate_payload is null then
    -- Manuell leverantörsbootstrap är fortsatt separat från verksamhetsmandat.
    if jsonb_array_length(invite.grants) not between 1 and 2 then raise exception 'Bootstrap denied' using errcode='42501'; end if;
    for p in select value from jsonb_array_elements(invite.grants) loop
      if jsonb_typeof(p) is distinct from 'object' or p->>'function' is null or p->>'function' not in ('kundadmin','granskare')
        or exists(select 1 from jsonb_object_keys(p) k where k<>'function') then raise exception 'Bootstrap denied' using errcode='42501'; end if;
      insert into public.access_assignments(membership_id,customer_id,function)
        values(member.id,c.id,(p->>'function')::public.access_function) returning id into new_id;
      assignments:=assignments||jsonb_build_array(jsonb_build_object('id',new_id,'function',p->>'function'));
    end loop;
  else raise exception 'Invitation issuer missing' using errcode='42501'; end if;
  if jsonb_array_length(assignments)=0 then raise exception 'Empty invitation' using errcode='42501'; end if;
  update public.invitations set used_at=clock_timestamp(),used_by_identity_id=ident.id where id=invite.id;
  return jsonb_build_object('invitationId',invite.id,'membershipId',member.id,'assignments',assignments,
    'customer',jsonb_build_object('id',c.id,'name',c.name),'emailMismatch',invite.expected_email is not null and invite.expected_email is distinct from ident.email);
end $$

-- Färsk serverklocka efter låsväntan och avgränsad kontokompatibilitet.
create or replace function public.phase3_mandate_is_valid(assignment_id uuid, require_current boolean default true)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare a public.access_assignments; p public.access_assignments;
  cursor_id uuid:=assignment_id; seen uuid[]:='{}'; check_time boolean:=require_current;
  server_now timestamptz:=clock_timestamp();
  today date:=(server_now at time zone 'Europe/Stockholm')::date;
begin
  loop
    if cursor_id is null or cursor_id=any(seen) or cardinality(seen)>=64 then return false; end if;
    seen:=array_append(seen,cursor_id);
    select * into a from public.access_assignments where id=cursor_id;
    if not found or a.ended_at is not null then return false; end if;
    -- Tidigare kundkonton behålls; äldre verksamhetsmandat ger ingen fas3-rätt.
    if a.profile_id is null then
      return a.function in ('kundadmin','granskare') and a.parent_assignment_id is null
        and a.valid_from<=today and (a.valid_to is null or today<=a.valid_to)
        and exists(select 1 from public.memberships m join public.customers c on c.id=m.customer_id
          where m.id=a.membership_id and m.status='active' and c.closed_at is null);
    end if;
    if not isfinite(a.valid_from) or (a.valid_to is not null and not isfinite(a.valid_to)) or not public.phase3_mandate_shape(a)
      or not exists(select 1 from public.memberships m join public.customers c on c.id=m.customer_id
        where m.id=a.membership_id and m.status='active' and c.closed_at is null)
      or (a.function in ('rektor','larare') and not public.phase3_staff_binding_is_valid(a.id))
      or (check_time and (a.valid_from>today or (a.valid_to is not null and a.valid_to<today)
        or (a.starts_at is not null and a.starts_at>server_now)
        or (a.ends_at is not null and a.ends_at<=server_now))) then return false; end if;
    if a.parent_assignment_id is null then
      return a.function in ('huvudman','elevhalsoansvarig','it','kundadmin','granskare');
    end if;
    select * into p from public.access_assignments where id=a.parent_assignment_id;
    if not found then return false; end if;
    if a.issued_by_assignment_id is distinct from p.id
      or a.customer_id is distinct from p.customer_id or a.organizer_id is distinct from p.organizer_id
      or not ((p.function='huvudman' and a.function='rektor')
        or (p.function='rektor' and a.function in ('larare','administrator','elevhalsa','support'))
        or (p.function='elevhalsoansvarig' and a.function='elevhalsa')
        or (p.function='kundadmin' and a.function in ('kundadmin','granskare')))
      or exists(select 1 from public.memberships x join public.memberships y on x.identity_id=y.identity_id
        where x.id=a.membership_id and y.id=p.membership_id)
      or a.valid_from<p.valid_from or (p.valid_to is not null and (a.valid_to is null or a.valid_to>p.valid_to))
      or (p.starts_at is not null and (a.starts_at is null or a.starts_at<p.starts_at))
      or (p.ends_at is not null and (a.ends_at is null or a.ends_at>p.ends_at))
      or exists(select 1 from public.mandate_units u where u.assignment_id=a.id
        and not exists(select 1 from public.mandate_units pu where pu.assignment_id=p.id and pu.unit_id=u.unit_id))
    then return false; end if;
    cursor_id:=p.id; check_time:=true;
  end loop;
end $$

-- Historiska kontoroller administreras av kundadmin utan elevmandat.
create or replace function public.phase3_revoke_mandate(target_id uuid) returns uuid
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; target public.access_assignments; legacy_account boolean;
begin
  a:=public.phase3_actor();
  select * into target from public.access_assignments where id=target_id;
  if not found then raise exception 'Revocation denied' using errcode='42501'; end if;
  legacy_account:=a.function='kundadmin' and target.function in ('kundadmin','granskare')
    and target.profile_id is null and target.parent_assignment_id is null
    and target.customer_id=a.customer_id and target.ended_at is null
    and not exists(select 1 from public.memberships x join public.memberships y on x.identity_id=y.identity_id
      where x.id=a.membership_id and y.id=target.membership_id);
  if not legacy_account and (target.parent_assignment_id is distinct from a.id
    or not public.phase3_mandate_is_valid(target.id,false)) then
    raise exception 'Revocation denied' using errcode='42501'; end if;
  update public.access_assignments set ended_at=clock_timestamp(),ended_by=a.membership_id where id=target.id;
  return target.id;
end $$

-- Avgränsad lokal IT-administration; inga externa anrop eller elevuppgifter.
create function public.phase3_connection(p_unit_id uuid, p_operation text default 'read', p_enabled boolean default null, p_expected_version integer default null)
returns jsonb language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare actor public.access_assignments; config public.local_connection_configs; current_version integer;
begin
  actor:=public.phase3_actor();
  if actor.function <> 'it' then raise exception 'Denied' using errcode='42501'; end if;
  if not exists(select 1 from public.mandate_units u where u.assignment_id=actor.id and u.unit_id=p_unit_id) then
    raise exception 'Not found' using errcode='P0002';
  end if;
  if p_operation is null or p_operation not in ('read','update','test') then raise exception 'Bad operation' using errcode='22023'; end if;
  select * into config from public.local_connection_configs where unit_id=p_unit_id for update;
  current_version:=coalesce(config.version,0);
  if p_operation='update' then
    if p_enabled is null or p_expected_version is null or p_expected_version<0 then raise exception 'Bad input' using errcode='22023'; end if;
    if current_version<>p_expected_version then raise exception 'Version conflict' using errcode='40001'; end if;
    insert into public.local_connection_configs(customer_id,organizer_id,unit_id,enabled,version,updated_by_assignment_id)
      values(actor.customer_id,actor.organizer_id,p_unit_id,p_enabled,current_version+1,actor.id)
      on conflict(unit_id) do update set enabled=excluded.enabled,version=excluded.version,
        updated_by_assignment_id=excluded.updated_by_assignment_id,updated_at=statement_timestamp()
      returning * into config;
  end if;
  return jsonb_build_object('unitId',p_unit_id,'enabled',coalesce(config.enabled,false),'version',coalesce(config.version,0),
    'result',case when p_operation='test' then case when coalesce(config.enabled,false) then 'synthetic_ok' else 'paused' end else null end);
end $$

-- Behåll befintlig maximal inbjudningstid 30 dygn.
create or replace function public.phase3_issue_invitation(payload jsonb) returns uuid
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; normalized jsonb; result uuid; expiry timestamptz;
begin
  a:=public.phase3_actor();
  if jsonb_typeof(payload) is distinct from 'object' or exists(select 1 from jsonb_object_keys(payload) k
    where k not in ('personName','expectedIssuer','expectedSubject','expectedEmail','tokenHashHex','expiresAt','mandates')) then
    raise exception 'Invalid invitation payload' using errcode='22023'; end if;
  expiry:=(payload->>'expiresAt')::timestamptz;
  if expiry is null or not isfinite(expiry) or expiry<=clock_timestamp() or expiry>clock_timestamp()+interval '30 days' then
    raise exception 'Invalid invitation expiry' using errcode='22023'; end if;
  normalized:=public.phase3_validate_invitation(a.id,payload->>'expectedIssuer',payload->>'expectedSubject',payload->'mandates');
  insert into public.invitations(customer_id,token_hash,invited_person_name,expected_issuer,expected_subject,
    expected_email,grants,issued_by,expires_at,issued_by_assignment_id,mandate_payload)
  values(a.customer_id,decode(payload->>'tokenHashHex','hex'),payload->>'personName',payload->>'expectedIssuer',payload->>'expectedSubject',
    payload->>'expectedEmail',(select jsonb_agg(jsonb_build_object('function',p->>'function')) from jsonb_array_elements(normalized) p),
    a.membership_id::text,expiry,a.id,jsonb_build_object('version',1,'mandates',normalized)) returning id into result;
  return result;
end $$

grant execute on function public.phase3_lock_customer(uuid),public.phase3_mandate_context(),
  public.phase3_list_mandates(),public.phase3_grant_mandate(jsonb),public.phase3_revoke_mandate(uuid),
  public.phase3_issue_invitation(jsonb),public.phase3_redeem_invitation(bytea,uuid),
  public.phase3_connection(uuid,text,boolean,integer),public.assignment_is_valid(public.access_assignments)
to skolplattform_worker

-- Synthetic retention only. No application role receives maintenance rights.
do $$ begin
  if not exists(select 1 from pg_roles where rolname='skolplattform_audit_maintenance') then
    create role skolplattform_audit_maintenance nologin noinherit;
  end if;
end $$

-- The protected SECURITY DEFINER entry point runs as postgres. The trigger
-- rechecks the server cutoff itself; caller-controlled GUCs cannot enable deletion.
create or replace function public.security_events_immutable() returns trigger
language plpgsql security invoker set search_path=pg_catalog,public as $$
begin
  if TG_OP='DELETE' and current_user='postgres' and exists (
    select 1 from public.audit_retention_policy p where p.customer_id=old.customer_id
      and p.profile_id='synthetic-v1'
      and old.occurred_at < transaction_timestamp()-make_interval(days=>p.retention_days)
  ) then return old; end if;
  raise exception 'security_events är oföränderlig' using errcode='42501';
end $$

create function public.purge_synthetic_audit(target_customer uuid) returns bigint
language plpgsql security definer set search_path=pg_catalog,public as $$
declare days integer; removed bigint;
begin
  select retention_days into days from public.audit_retention_policy
    where customer_id=target_customer and profile_id='synthetic-v1' for share;
  if not found then raise exception 'Retention is not configured' using errcode='42501'; end if;
  delete from public.security_events where customer_id=target_customer
    and occurred_at < transaction_timestamp()-make_interval(days=>days);
  get diagnostics removed = row_count;
  return removed;
end $$

-- Presentation metadata only for already-administrable mandates and IT schools.
create or replace function public.phase3_list_mandates() returns jsonb
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; result jsonb;
begin
  a:=public.phase3_actor();
  select coalesce(jsonb_agg(public.phase3_assignment_document(t.id)||jsonb_build_object(
    'displayName',coalesce(nullif(i.display_name,''),'Namngiven personal'),
    'schools',coalesce((select jsonb_agg(jsonb_build_object('id',u.unit_id,'name',s.name) order by s.name,u.unit_id)
      from public.mandate_units u join public.school_units s on s.id=u.unit_id where u.assignment_id=t.id),'[]'::jsonb),
    'status',case when t.valid_from > (clock_timestamp() at time zone 'Europe/Stockholm')::date
      or t.starts_at > clock_timestamp() then 'kommande' else 'giltigt' end,
    'approverName',case when t.approved_by_assignment_id=a.id then
      (select pi.display_name from public.memberships pm join public.identities pi on pi.id=pm.identity_id where pm.id=a.membership_id) else null end
  ) order by i.display_name,t.id),'[]') into result
  from public.access_assignments t join public.memberships m on m.id=t.membership_id
  join public.identities i on i.id=m.identity_id
  where t.parent_assignment_id=a.id and public.phase3_mandate_is_valid(t.id,false);
  return result;
end $$

create function public.phase3_connection_schools() returns jsonb
language plpgsql volatile security definer set search_path=pg_catalog,public as $$
declare a public.access_assignments; result jsonb;
begin
  a:=public.phase3_actor();
  if a.function<>'it' then raise exception 'IT mandate required' using errcode='42501'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',u.unit_id,'name',s.name) order by s.name,u.unit_id),'[]') into result
    from public.mandate_units u join public.school_units s on s.id=u.unit_id where u.assignment_id=a.id;
  return result;
end $$

-- 2. Formprövningen: exakt en skola och antingen exakt en elev eller minst en
-- grupp, aldrig båda och aldrig ärenden. Övriga grenar är oförändrade från
-- 20260924130000.
create or replace function public.phase3_mandate_shape(a public.access_assignments)
returns boolean language plpgsql stable security invoker set search_path=pg_catalog,public as $$
declare units integer; groups integer; pupils integer; cases integer;
begin
  if a.profile_id is distinct from 'synthetic-v1' or a.scope_kind is null then return false; end if;
  select count(*) into units from public.mandate_units where assignment_id=a.id;
  select count(*) into groups from public.mandate_groups where assignment_id=a.id;
  select count(*) into pupils from public.mandate_pupils where assignment_id=a.id;
  select count(*) into cases from public.mandate_cases where assignment_id=a.id;
  if a.function in ('kundadmin','granskare') then
    return a.organizer_id is null and a.scope_kind='school' and units+groups+pupils+cases=0;
  end if;
  if units=0 or a.organizer_id is null then return false; end if;
  if a.function='larare' then return a.scope_kind='group' and groups>0 and pupils+cases=0; end if;
  if a.function='support' then
    return units=1 and cases=0
      and ((a.scope_kind='pupil' and pupils=1 and groups=0)
        or (a.scope_kind='group' and groups>0 and pupils=0))
      and a.parent_assignment_id is not null and a.approved_by_assignment_id=a.parent_assignment_id
      and a.starts_at is not null and a.ends_at is not null
      and a.ends_at-a.starts_at <= interval '60 minutes'
      and a.purpose_code='synthetic-troubleshooting';
  end if;
  if a.function='elevhalsa' then
    return (a.scope_kind='school' and groups+pupils+cases=0)
      or (a.scope_kind='pupil' and pupils>0 and groups+cases=0)
      or (a.scope_kind='case' and cases>0 and groups+pupils=0);
  end if;
  return a.scope_kind='school' and groups+pupils+cases=0;
end $$

-- Ren formatkontroll: TEST-prefix, faktiskt kalenderdatum och Luhn YYMMDDNNNK.
-- Allowlist tillkommer via FK, aldrig genom formatkontrollen ensam.
create function public.phase4_synthetic_birth_date(value text) returns date
language plpgsql immutable strict set search_path = pg_catalog as $$
declare born date; digits text; total integer := 0; digit integer; i integer;
begin
  if length(value) <> 18 or value !~ '^TEST-[0-9]{8}-[0-9]{4}$' then return null; end if;
  begin
    born := make_date(substring(value,6,4)::integer,substring(value,10,2)::integer,substring(value,12,2)::integer);
  exception when datetime_field_overflow then return null;
  end;
  digits := substring(value,8,6) || substring(value,15,4);
  for i in 1..10 loop
    digit := substring(digits,i,1)::integer * case when i % 2 = 1 then 2 else 1 end;
    total := total + digit / 10 + digit % 10;
  end loop;
  if total % 10 <> 0 then return null; end if;
  return born;
end $$

-- Avvisa tvetydig gammal grupptillhörighet: välj aldrig tyst bort ett mandat.
do $$begin
  if exists(select 1 from public.phase3_probe_group_members group by pupil_id having count(*)>1) then
    raise exception 'Ambiguous probe class membership' using errcode='23514';
